const event = $json.body ?? $json;
const run = event.workflow_run ?? {};
const repository = event.repository ?? run.repository ?? {};
const owner = repository.owner?.login ?? run.repository?.owner?.login;
const repo = repository.name ?? run.repository?.name;
const runId = Number(run.id ?? event.run_id);
const headSha = run.head_sha ?? event.head_sha;

if (!owner || !repo || !Number.isSafeInteger(runId) || !headSha) {
  throw new Error('Webhook must contain repository owner/name, workflow run id and head SHA');
}
if (run.conclusion && run.conclusion !== 'failure') {
  throw new Error(`Expected a failed run, got conclusion=${run.conclusion}`);
}

return [{
  json: {
    owner,
    repo,
    run_id: runId,
    head_sha: headSha,
    workflow_url: run.html_url ?? '',
    input_source: event.workflow_run ? 'github_webhook' : 'test_fixture',
    chatInput: `Analyze failed GitHub Actions run ${runId} in ${owner}/${repo} at commit ${headSha}. Follow the CI failure analysis skill exactly. Use only the supplied MCP tools. Return Markdown with every mandatory section.`
  }
}];

const result = $json.output;
if (typeof result !== 'string' || result.trim().length === 0) {
  throw new Error('Agent returned an empty report');
}

const report = result
  .replace(/^```(?:markdown)?\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

const requiredHeadings = [
  '# Отчёт о сбое CI',
  '## Подтверждённые факты',
  '## Гипотезы',
  '## Рекомендуемые действия',
  '## Владелец и эскалация',
  '## Источники'
];
const missing = requiredHeadings.filter((heading) => !report.includes(heading));
if (missing.length) {
  throw new Error(`Report is missing required headings: ${missing.join(', ')}`);
}

const meta = $('Validate Event').first().json;
const safeRepo = String(meta.repo).replace(/[^a-zA-Z0-9._-]/g, '-');
return [{
  json: {
    report: `${report}\n`,
    file_name: `ci-${safeRepo}-${meta.run_id}.md`,
    run_id: meta.run_id,
    repository: `${meta.owner}/${meta.repo}`
  }
}];
